# 008_bpm_il_tempo_perso_si_recupera.py
#
# I BPM CHE CALANO CON L'EXPANDER: il tempo perso non si butta piu' via.
#
# IL DIFETTO. Nel ciclo di riproduzione c'era:
#
#     if delta_time > 0.05:
#         delta_time = 0.05      # "limita i salti dopo un lag"
#
# Il tempo della musica avanza di quanto e' passato davvero. Ma se un giro
# tardava 300 ms, la musica ne faceva 50: gli altri 250 SPARIVANO. Non
# rallentava e basta - perdeva pezzi di brano, per sempre.
#
# PERCHE' SOLO COI MIDI, E SOLO CON L'EXPANDER. Il ritardo del ciclo c'e'
# sempre: e' codice Python, e mentre la finestra lavora (la ricerca, lo
# spostamento fra i preferiti, qualunque cosa) il thread non riprende il turno.
# Ma:
#   - con MP3 e video il suono lo fa VLC/BASS, motori nativi: Python non tiene
#     il tempo e non se ne accorge nessuno;
#   - col MIDI su SoundFont il ciclo ritarda uguale, pero' le note vanno a un
#     synth dentro il programma, con un buffer audio davanti che assorbe;
#   - col MIDI sull'EXPANDER non c'e' nessun buffer: ogni nota deve uscire al
#     millisecondo giusto verso una scatola fuori dal computer. Un ritardo e'
#     un ritardo, e il taglio se lo mangia.
# E' l'unico caso in cui Python tiene il tempo in diretta senza rete.
#
# MISURATO sul PC del cliente (spia MIDI-TIMING, patch 006):
#     la musica scendeva al 52% del dovuto - meta' velocita' - e in 42 secondi
#     sparivano 5,2 secondi di brano. Il calo era progressivo: 91% ... 52%.
#
# COSA CAMBIA. Il ritardo diventa un DEBITO che si ripaga poco per volta, al
# massimo il 25% per ciclo. Non si recupera tutto in un colpo APPOSTA: mandare
# trecento millisecondi di note insieme all'expander vuol dire intasarlo e
# peggiorare - ed e' l'errore che avevo gia' fatto il 3 settembre, quando la
# cura peggiorava le cose. Cosi' invece si torna in pari in un secondo o due,
# senza raffiche. Il debito ha un tetto di 2 secondi: oltre quello il buco e'
# troppo grande per colmarlo suonando piu' in fretta e si rinuncia.
#
# SIMULATO con i ritardi che riproducono il log del cliente:
#     prima 81% del dovuto  ->  dopo 97%
#     prima 78%             ->  dopo 94%
#
# NON tocca nient'altro: non i thread, non il turno fra loro, non i messaggi
# MIDI. Solo il conto del tempo.
#
# ⛔ Se peggiora, si toglie questa patch e tutto torna com'era: il punto di
#    ripristino e' il tag RESTORE_pre_timing_midi_20260904_1154.

CODICE = 'def _playback_loop(self):\n    """Loop di riproduzione MIDI con timing ad alta precisione.\n    ZERO CALLBACK dal thread audio — nessuna interazione con Tkinter/GIL.\n    Su Windows usa timeBeginPeriod(1) per risoluzione timer 1ms reale.\n    Tutti gli attributi sono pre-cached come variabili locali per velocità."""\n\n    # ✅ WINDOWS: attiva risoluzione timer 1ms (default è 15.6ms!)\n    _winmm = None\n    if sys.platform == \'win32\':\n        try:\n            import ctypes\n            _winmm = ctypes.windll.winmm\n            _winmm.timeBeginPeriod(1)\n        except:\n            _winmm = None\n        # ✅ Alza priorità thread audio\n        try:\n            import ctypes\n            handle = ctypes.windll.kernel32.GetCurrentThread()\n            ctypes.windll.kernel32.SetThreadPriority(handle, 2)  # THREAD_PRIORITY_HIGHEST\n        except:\n            pass\n\n    try:\n        events = self._events\n        num_events = len(events)\n        event_index = 0\n\n        # ✅ RICOSTRUISCI STATO per seek: processa setup senza suonare note\n        if self.current_tick > 0:\n            self._rebuild_state_at_tick(self.current_tick)\n\n        # Trova primo evento >= current_tick\n        start_tick = self.current_tick\n        while event_index < num_events and events[event_index][0] < start_tick:\n            event_index += 1\n\n        # ✅ Pre-cache TUTTO come locals (evita attribute lookup nel hot loop)\n        _synth = self.synth\n        _sfid = self.sfid\n        _stop = self._stop_event\n        _perf = time.perf_counter\n        _sleep = time.sleep\n        _tpb = self.ticks_per_beat\n        _channel_muted = self.channel_muted\n        _channel_volumes = self.channel_volumes\n        _channel_pan = self.channel_pan\n        _channel_expression = self.channel_expression\n        _channel_sustain = self.channel_sustain\n        _channel_reverb_send = self.channel_reverb_send\n        _channel_chorus_send = self.channel_chorus_send\n        _channel_bank_msb = self.channel_bank_msb\n        _channel_bank_lsb = self.channel_bank_lsb\n        _channel_programs = self.channel_programs\n        _active_notes = self.active_notes\n        _channel_dirty = self._channel_dirty  # ✅ Flag per UI polling\n\n        # Synth methods pre-cached\n        _noteon = _synth.noteon\n        _noteoff = _synth.noteoff\n        _cc = _synth.cc\n        _pitch_bend = _synth.pitch_bend\n        _program_select = _synth.program_select\n\n        # 🎛️ Rimappa strumenti: carico dal DB alla prima riproduzione (se il\n        # Mixer non l\'ha gia\' impostata) e la pre-cache per il hot loop.\n        if not self._instrmap_loaded:\n            try:\n                self.instrument_map = FluidSynthPlayer.load_instrument_remap()\n            except Exception:\n                pass\n            self._instrmap_loaded = True\n        _instr_map = self.instrument_map\n\n        # 🕵️ SPIA DEL TIMING. Scrive nel log di KaraDom (log/karadom_debug.log,\n        #    quello che il cliente sa gia\' inviare dal menu) quanto resta\n        #    indietro questo thread mentre suona. Serve a misurare DENTRO il\n        #    programma vero: i ritardi qui dipendono da Tk, dai 35 thread e\n        #    dalla porta MIDI, cose che su un banco di prova non si\n        #    riproducono - e infatti una cura tarata li\' ha peggiorato.\n        #    Se il log non e\' attivo (avvio normale) non si raccoglie niente\n        #    e non costa niente.\n        try:\n            from .debug_logger import DEBUG as _spia, dbg as _dbg\n        except Exception:\n            _spia, _dbg = False, None\n        _sp_n = _sp_sopra = _sp_sopra_tot = 0\n        _sp_max = _sp_max_tot = 0.0\n        _sp_somma = _sp_persi = _sp_persi_tot = 0.0\n        _sp_inizio = _sp_quando = _perf()\n\n        last_time = _perf()\n        accumulated_ticks = float(start_tick)\n        # il tempo che il taglio dei 50 ms farebbe sparire,\n        # da restituire poco per volta\n        _debito = 0.0\n        _DEBITO_MAX = 2.0\n        current_tempo = self._get_tempo_at_tick(start_tick)\n        speed = self._speed\n        pitch_offset = self._pitch_semitones  # ✅ Offset utente in semitoni\n\n        while not _stop.is_set() and event_index < num_events:\n\n            # Gestisci pausa (low-frequency check)\n            if self.is_paused:\n                while self.is_paused and not _stop.is_set():\n                    _sleep(0.01)\n                last_time = _perf()\n                speed = self._speed  # Re-read dopo pausa\n                pitch_offset = self._pitch_semitones  # Re-read pitch dopo pausa\n                continue\n\n            if _stop.is_set():\n                break\n\n            # ✅ Timing ad alta precisione\n            now = _perf()\n            delta_time = now - last_time\n            last_time = now\n\n            # ✅ Re-read pitch offset (trasposizione nota)\n            new_pitch = self._pitch_semitones\n            if new_pitch != pitch_offset:\n                for _ch in range(16):\n                    _cc(_ch, 123, 0)      # All Notes Off\n                    _pitch_bend(_ch, 8192) # Reset pitch bend\n                pitch_offset = new_pitch\n                print(f"🎵 MIDI transpose: {pitch_offset:+d} semitoni")\n\n            if _spia:\n                _sp_n += 1\n                _r = delta_time * 1000.0\n                _sp_somma += _r\n                if _r > _sp_max:\n                    _sp_max = _r\n                if delta_time > 0.05:\n                    _sp_sopra += 1\n                    _sp_persi += _r - 50.0     # musica che il taglio fa sparire\n                if now - _sp_quando >= 5.0:\n                    # una riga solo se in questi 5 secondi si e\' perso tempo:\n                    # se e\' filato liscio il log non si sporca\n                    if _sp_sopra:\n                        _dbg("MIDI-TIMING",\n                             "expander=%s  cicli=%d  ritardo medio=%.1f ms  "\n                             "max=%.0f ms  oltre 50ms=%d  musica persa=%.0f ms" % (\n                                 "si" if getattr(self, "is_expander", False) else "no",\n                                 _sp_n, _sp_somma / max(1, _sp_n), _sp_max,\n                                 _sp_sopra, _sp_persi))\n                    _sp_sopra_tot += _sp_sopra\n                    _sp_persi_tot += _sp_persi\n                    if _sp_max > _sp_max_tot:\n                        _sp_max_tot = _sp_max\n                    _sp_n = _sp_sopra = 0\n                    _sp_max = 0.0\n                    _sp_somma = _sp_persi = 0.0\n                    _sp_quando = now\n\n            # ✅ IL TEMPO PERSO NON SI BUTTA PIU\' VIA (4 set 2026)\n            # Prima c\'era: se delta_time > 0.05 -> delta_time = 0.05. Cioe\'\n            # un giro che tardava 300 ms faceva avanzare la musica di 50: gli\n            # altri 250 sparivano PER SEMPRE. Con l\'expander succede di\n            # continuo - ogni nota esce dal sistema, il thread molla il turno\n            # e se la finestra sta lavorando (la ricerca, i preferiti,\n            # qualsiasi cosa) non lo riprende in tempo. Misurato sul PC\n            # dell\'utente: la musica scendeva al 52% del dovuto, cioe\' meta\'\n            # velocita\', e in 42 secondi sparivano 5,2 secondi di brano.\n            #\n            # Adesso il ritardo diventa un DEBITO che si ripaga poco per\n            # volta. Non si recupera in un colpo apposta: mandare trecento\n            # millisecondi di note tutte insieme all\'expander vuol dire\n            # intasarlo e peggiorare. Si restituisce al massimo il 25% per\n            # ciclo, cosi\' si torna in pari in un secondo o due senza\n            # raffiche.\n            #\n            # ⚠️ Il debito ha un tetto: oltre _DEBITO_MAX il buco e\' troppo\n            # grande per colmarlo suonando piu\' in fretta (il PC era occupato,\n            # o il brano era fermo) e si rinuncia - meglio perdere quel pezzo\n            # che accelerare per dieci secondi.\n            if delta_time > 0.05:\n                _debito += delta_time - 0.05\n                if _debito > _DEBITO_MAX:\n                    _debito = _DEBITO_MAX\n                delta_time = 0.05\n            elif _debito > 0.0:\n                _extra = _debito * 0.25\n                if _extra > delta_time * 0.25:\n                    _extra = delta_time * 0.25      # mai piu\' del 25% in piu\'\n                delta_time += _extra\n                _debito -= _extra\n                if _debito < 0.001:\n                    _debito = 0.0\n\n            # Converti in ticks usando il tempo corrente + speed\n            ticks_per_second = (_tpb * 1000000.0) / current_tempo\n            accumulated_ticks += delta_time * speed * ticks_per_second\n\n            cur_tick = int(accumulated_ticks)\n            self.current_tick = cur_tick\n\n            # ✅ PROCESS EVENTI — hot loop inlined, zero callback\n            while event_index < num_events:\n                ev_tick, ev_track, msg = events[event_index]\n                if ev_tick > cur_tick:\n                    break\n                event_index += 1\n\n                msg_type = msg.type\n\n                if msg_type == \'note_on\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    vel = msg.velocity\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    if vel > 0:\n                        _noteon(ch, note, vel)\n                        _active_notes[ch] += 1\n                        _channel_dirty[ch] = True  # ✅ Flag per UI, non callback\n                    else:\n                        _noteoff(ch, note)\n                        n = _active_notes[ch] - 1\n                        _active_notes[ch] = n if n > 0 else 0\n\n                elif msg_type == \'note_off\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    _noteoff(ch, note)\n                    n = _active_notes[ch] - 1\n                    _active_notes[ch] = n if n > 0 else 0\n\n                elif msg_type == \'control_change\':\n                    ch = msg.channel\n                    cc_num = msg.control\n                    val = msg.value\n                    if cc_num == 0:\n                        _channel_bank_msb[ch] = val\n                    elif cc_num == 32:\n                        _channel_bank_lsb[ch] = val\n                    elif cc_num == 7:\n                        _channel_volumes[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, val)\n                    elif cc_num == 10:\n                        _channel_pan[ch] = val\n                        _cc(ch, 10, val)\n                    elif cc_num == 11:\n                        _channel_expression[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 11, val)\n                    elif cc_num == 64:\n                        _channel_sustain[ch] = val\n                        _cc(ch, 64, val)\n                    elif cc_num == 91:\n                        _channel_reverb_send[ch] = val\n                        _cc(ch, 91, val)\n                    elif cc_num == 93:\n                        _channel_chorus_send[ch] = val\n                        _cc(ch, 93, val)\n                    elif cc_num == 121:\n                        _cc(ch, 121, 0)\n                        _channel_expression[ch] = 127\n                        _channel_sustain[ch] = 0\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, _channel_volumes[ch])\n                            _cc(ch, 11, 127)\n                        _cc(ch, 10, _channel_pan[ch])\n                    else:\n                        _cc(ch, cc_num, val)\n\n                elif msg_type == \'program_change\':\n                    if _sfid is not None:\n                        ch = msg.channel\n                        bank = _channel_bank_msb[ch]\n                        if ch == 9:\n                            bank = 128\n                        prog = msg.program\n                        # 🎛️ sostituzione strumento di default (rimappa globale)\n                        if _instr_map:\n                            _r = _instr_map.get((ch == 9, prog, bank))\n                            if _r is not None:\n                                prog, bank = _r\n                        _program_select(ch, _sfid, bank, prog)\n                        _channel_programs[ch] = prog\n\n                elif msg_type == \'set_tempo\':\n                    current_tempo = msg.tempo\n                    self.tempo = current_tempo\n\n                elif msg_type == \'pitchwheel\':\n                    # ✅ Pitchwheel dal file: passa diretto (range default 2 semitoni)\n                    # La trasposizione è gestita via note transpose, non pitch bend\n                    bend = int(8192 + msg.pitch)\n                    bend = max(0, min(16383, bend))\n                    _pitch_bend(msg.channel, bend)\n\n                elif msg_type == \'sysex\':\n                    self._process_sysex(msg)\n\n                elif msg_type == \'aftertouch\':\n                    try:\n                        _synth.channel_pressure(msg.channel, msg.value)\n                    except:\n                        pass\n\n                elif msg_type == \'polytouch\':\n                    try:\n                        _synth.key_pressure(msg.channel, msg.note, msg.value)\n                    except:\n                        pass\n\n            # ✅ Re-read speed e pitch (potrebbero cambiare da UI)\n            speed = self._speed\n            pitch_offset = self._pitch_semitones\n\n            # ✅ Sleep adattivo fino al prossimo evento\n            if event_index < num_events:\n                next_tick = events[event_index][0]\n                ticks_remaining = next_tick - accumulated_ticks\n                if ticks_remaining > 0 and ticks_per_second > 0:\n                    sleep_time = ticks_remaining / ticks_per_second\n                    if speed > 0:\n                        sleep_time /= speed\n                    # Cap a max 3ms, dormi 80% del tempo calcolato\n                    sleep_time = min(sleep_time * 0.8, 0.003)\n                    if sleep_time > 0.0005:\n                        _sleep(sleep_time)\n                else:\n                    _sleep(0.001)\n            else:\n                _sleep(0.001)\n\n        # Fine riproduzione\n        if not _stop.is_set():\n            self.is_playing = False\n            self._all_notes_off()\n            print("🎵 Riproduzione MIDI terminata")\n\n            if self.on_playback_end:\n                try:\n                    self.on_playback_end()\n                except:\n                    pass\n\n    except Exception as e:\n        print(f"❌ Errore playback: {e}")\n        import traceback\n        traceback.print_exc()\n    finally:\n        if _spia and _dbg is not None:\n            try:\n                _durata = _perf() - _sp_inizio\n                _sp_sopra_tot += _sp_sopra\n                _sp_persi_tot += _sp_persi\n                if _sp_max > _sp_max_tot:\n                    _sp_max_tot = _sp_max\n                _dbg("MIDI-TIMING",\n                     "RIEPILOGO brano: durata %.0f s, expander=%s, "\n                     "ritardi oltre 50ms: %d, ritardo peggiore %.0f ms, "\n                     "musica persa in tutto %.0f ms (%.1f%% del brano)" % (\n                         _durata,\n                         "si" if getattr(self, "is_expander", False) else "no",\n                         _sp_sopra_tot, _sp_max_tot, _sp_persi_tot,\n                         (_sp_persi_tot / 10.0 / _durata) if _durata > 0 else 0.0))\n            except Exception:\n                pass\n        # ✅ WINDOWS: ripristina risoluzione timer default\n        if _winmm:\n            try:\n                _winmm.timeEndPeriod(1)\n            except:\n                pass\n\n'


def apply():
    import moduli.fluidsynth_player as fp
    P = getattr(fp, "FluidSynthPlayer", None)
    if P is None or not hasattr(P, "_playback_loop"):
        print("patch 008: motore MIDI diverso, salto")
        return False
    # il ciclo si compila NELLO SPAZIO DEI NOMI del modulo: dentro usa decine di
    # nomi globali suoi (time, sys, ctypes, le costanti) che qui non ci sono
    spazio = fp.__dict__
    exec(compile(CODICE, "<patch008>", "exec"), spazio)
    P._playback_loop = spazio["_playback_loop"]
    print("patch 008: il tempo perso si recupera (i BPM non calano piu' "
          "con l'expander)")
    return True


try:
    apply()
except Exception as _e:
    print("patch 008: %s" % _e)
